<?php
require_once dirname(dirname(__DIR__)).'/src/bootstrap.php';$user=Auth::requireRole('hospital');$hospital=current_hospital($user);if(!$hospital){http_response_code(403);exit('No active hospital is assigned to this account.');}
$q=db()->prepare("SELECT e.*,(SELECT COUNT(*) FROM emergency_invites i WHERE i.emergency_id=e.id AND i.status='accepted') accepted,(SELECT COUNT(*) FROM hospital_referrals r WHERE r.emergency_id=e.id) referrals FROM emergency_requests e WHERE e.hospital_id=? ORDER BY e.created_at DESC LIMIT 20");$q->execute([(int)$hospital['id']]);$rows=$q->fetchAll();
$incoming=db()->prepare("SELECT COUNT(*) FROM hospital_referrals WHERE target_hospital_id=? AND status='pending'");$incoming->execute([(int)$hospital['id']]);$pendingRef=(int)$incoming->fetchColumn();
$campaigns=db()->prepare("SELECT COUNT(*) FROM donation_campaigns WHERE hospital_id=? AND status='active' AND event_date>=CURDATE()");$campaigns->execute([(int)$hospital['id']]);$activeCampaigns=(int)$campaigns->fetchColumn();
$pageTitle='Hospital Dashboard';require dirname(dirname(__DIR__)).'/src/templates/header.php';?>
<section class="dashboard"><div class="container"><div class="dash-head"><div><div class="eyebrow">Hospital workspace</div><h1><?=e($hospital['name'])?></h1><p class="page-note">Manage emergency requests and supporting coordination modules from one simple workspace.</p></div><a class="btn" href="<?=e(url('hospital/emergency-create.php'))?>">Create Emergency Request</a></div><?=hospital_nav($user)?><div class="metrics"><div class="metric"><span>Open emergencies</span><strong><?php $x=0;foreach($rows as $r)if($r['status']==='open')$x++;echo e((string)$x);?></strong></div><div class="metric"><span>Pending referrals</span><strong><?=e((string)$pendingRef)?></strong></div><div class="metric"><span>Active campaigns</span><strong><?=e((string)$activeCampaigns)?></strong></div><div class="metric"><span>District</span><strong style="font-size:1.25rem"><?=e($hospital['district'])?></strong></div></div><h2>Recent emergency requests</h2><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Blood</th><th>District</th><th>Urgency</th><th>Accepted</th><th>Referrals</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty">No emergency requests yet.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td>#<?=e((string)$r['id'])?></td><td><?=e($r['blood_group'])?></td><td><?=e($r['district'])?></td><td><?=e(ucfirst($r['urgency']))?></td><td><?=e((string)$r['accepted'])?> / <?=e((string)$r['required_donors'])?></td><td><?=e((string)$r['referrals'])?></td><td><span class="badge <?=$r['status']==='fulfilled'?'green':($r['status']==='open'?'amber':'gray')?>"><?=e($r['status'])?></span></td><td><a href="<?=e(url('hospital/emergency-view.php?id='.(int)$r['id']))?>">Open</a></td></tr><?php endforeach;?></tbody></table></div></div></section>
<?php require dirname(dirname(__DIR__)).'/src/templates/footer.php';?>
